<?php
requireAdmin();
$types=[''=>'כל הסוגים','place'=>'מקום','trip'=>'מסלול','post'=>'פרסום','comment'=>'תגובה','translation'=>'תרגום'];
$filters=[];foreach(['type','state','language','city','author','q'] as $key)$filters[$key]=mb_substr(is_string($_GET[$key]??null)?$_GET[$key]:'',0,150);
if(!isset($types[$filters['type']]))$filters['type']='';
if(!in_array($filters['state'],['pending','published','approved','rejected','blocked','private','needs_info','removed',''],true))$filters['state']='pending';
if(!isset($_GET['state']))$filters['state']='pending';
$union="SELECT 'place' kind,p.id,p.owner,p.state,p.created stamp,p.document,0 revision FROM member_places p
 UNION ALL SELECT 'trip',t.id,t.owner,CASE WHEN t.pending_plan IS NOT NULL THEN 'pending' ELSE t.state END,t.updated,COALESCE(t.pending_plan,t.public_plan,t.plan),t.revision FROM member_trips t
 UNION ALL SELECT 'post',p.id,p.owner,p.state,p.created,l.document,0 FROM network_posts p JOIN network_localizations l ON l.kind='post' AND l.target=p.id
 UNION ALL SELECT 'comment',c.id,c.owner,c.state,c.created,json_object('title',substr(c.body,1,100),'description',c.body,'language',c.language),0 FROM network_comments c
 UNION ALL SELECT 'translation',s.id,s.owner,s.state,s.created,json_set(s.document,'$.language',s.language),s.base_version FROM network_submissions s";
$where=" WHERE (?='' OR x.kind=?) AND (?='' OR x.state=?) AND (?='' OR json_extract(x.document,'$.language')=?) AND (?='' OR json_extract(x.document,'$.city')=?) AND (?='' OR m.handle=?) AND (?='' OR x.document LIKE ?)";
$args=[];foreach(['type','state','language','city','author','q'] as $key){$args[]=$filters[$key];$args[]=$key==='q'?'%'.$filters[$key].'%':$filters[$key];}
$from=" FROM ($union) x JOIN members m ON m.id=x.owner".$where;
$total=(int)socialQuery('SELECT COUNT(*)'.$from,$args)->fetchColumn();$page=max(1,min(max(1,(int)ceil($total/20)),(int)($_GET['page']??1)));
$rows=socialQuery('SELECT x.*,m.handle'.$from.' ORDER BY x.stamp,x.id LIMIT 20 OFFSET '.(($page-1)*20),$args)->fetchAll();
$pageUrl=fn($n)=>'/KNISA/community/?'.http_build_query($filters+['page'=>$n]);
ob_start();?><section class="social-page"><h1>תור בדיקה</h1><?php if($error):?><p role="alert" class="notice error"><?=e($error)?></p><?php endif?><?php if($notice):?><div id="moderation-status" class="notice" role="status" tabindex="-1"><strong><?=e($notice)?></strong><p data-review-next-message>התור עודכן. אפשר להמשיך לפריט הבא.</p></div><?php endif?><p><a href="/KNISA/community/?view=history">היסטוריה, דיווחים, משתמשים ומדדים</a></p><form method="get" class="queue-filters"><label>סוג<select name="type"><?php foreach($types as $key=>$label):?><option value="<?=$key?>" <?=$filters['type']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><label>מצב<select name="state"><?php foreach(['pending'=>'ממתין',''=>'כל המצבים','published'=>'פורסם','approved'=>'מקום מאושר','rejected'=>'נדחה','blocked'=>'מוסתר','private'=>'פרטי','needs_info'=>'להשלמה','removed'=>'הוסר'] as $key=>$label):?><option value="<?=$key?>" <?=$filters['state']===$key?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label>שפה<select name="language"><option value="">כל השפות</option><?php foreach(enabledLanguages() as $key=>$language):?><option value="<?=e($key)?>" <?=$filters['language']===$key?'selected':''?>><?=e($language['label'])?></option><?php endforeach?></select></label><label>עיר<input name="city" value="<?=e($filters['city'])?>"></label><label>שם משתמש<input name="author" value="<?=e($filters['author'])?>"></label><label>חיפוש<input name="q" value="<?=e($filters['q'])?>"></label><button>סינון</button></form><p role="status"><span><?=$total?></span> <span>פריטים</span> · <span>עמוד</span> <span><?=$page?></span> <span>מתוך</span> <span><?=max(1,(int)ceil($total/20))?></span></p><?php if(!$rows):?><p class="notice">אין פריטים בחיתוך שנבחר. הרשימה נטענה בהצלחה.</p><?php endif?>
<?php foreach($rows as $row):$document=json_decode($row['document'],true)?:[];?><article class="social-card" <?=$row['state']==='pending'?'data-review-pending':''?>><h2><?=e($document['public_title']??$document['title']??$document['city']??$row['id'])?></h2><p><?=e($types[$row['kind']])?> · <?=e(['pending'=>'ממתין','published'=>'פורסם','approved'=>'מאושר','private'=>'פרטי','rejected'=>'נדחה','blocked'=>'מוסתר','needs_info'=>'להשלמה','removed'=>'הוסר'][$row['state']]??$row['state'])?> · @<?=e($row['handle'])?> · <?=e($document['language']??'')?></p><p><?=e($document['city']??'')?> · <?=gmdate('Y-m-d H:i',(int)$row['stamp'])?> UTC</p><details><summary>פתיחת תוכן ופרטי בדיקה</summary><p dir="auto"><?=nl2br(e($document['body']??$document['description']??$document['summary']??''))?></p><?php if($row['kind']==='trip'):?><ol><?php foreach($document['items']??[] as $stop):?><li><?=e($stop['title']??$stop['id'])?> · יום <?=(int)($stop['day']??0)?></li><?php endforeach?></ol><?php endif?><?php foreach($document['photos']??array_filter([$document['photo']??'']) as $photo):?><img loading="lazy" src="/community/media/<?=e($photo)?>/" alt="תמונה לבדיקה" width="250"><?php endforeach?><dl><?php foreach(['source_url','address','hours','latitude','longitude'] as $key):?><dt><?=e($key)?></dt><dd><?=e((string)($document[$key]??'לא סופק'))?></dd><?php endforeach?></dl><p>מזהה: <?=e($row['id'])?> · גרסה לבדיקה: <?=e(substr(networkReviewVersion($row['kind'],$row['id']),0,12))?></p></details><?php socialAdminActions($row['kind'],$row['id'],(int)$row['revision']);?></article><?php endforeach?><nav aria-label="עמודי התור"><?php if($page>1):?><a class="button secondary" href="<?=e($pageUrl($page-1))?>">הקודם</a><?php endif?><?php if($page*20<$total):?><a class="button secondary" href="<?=e($pageUrl($page+1))?>">הבא</a><?php endif?></nav></section><script src="/assets/moderation-queue.js?v=3" defer></script><?php $content=ob_get_clean();require ROOT.'/views/layout.php';
